 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→}
 21→
 22→export interface Result {
 23→  id: string;
 24→  resume_id: string;
 25→  skill_score: number;
 26→  experience_score: number;
 27→  education_score: number;
 28→  overall_score: number;
 29→  missing_skills: string[];
 30→  red_flags: any;
 31→  summary: string | null;
 32→  interview_questions: any;
 33→  filename: string;
 34→  file_path: string | null;
 35→  candidate_name: string | null;
 36→  candidate_email?: string | null;
 37→  candidate_phone?: string | null;
 38→  candidate_location?: string | null;
 39→  // Dynamic scoring fields
 40→  hard_fit?: boolean;
 41→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 42→  confidence?: number;
 43→  strengths_json?: string[];
 44→  gaps_json?: string[];
 45→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
 46→  matched_must_haves?: string[];
 47→  missing_must_haves?: string[];
 48→  scoring_version?: string;
 49→  pending?: boolean;
 50→}
