 60→const Index = () => {
 61→  const { user } = useAuth();
 62→
 63→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 64→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 65→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 66→  const [results, setResults] = useState<Result[]>([]);
 67→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 68→  const [authOpen, setAuthOpen] = useState(false);
 69→
 70→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 71→
 72→  const fetchPastJobs = useCallback(async () => {
 73→    if (!user) return;
 74→    setLoadingPastJobs(true);
 75→    try {
 76→      const { data: jobs } = await supabase
 77→        .from("jobs")
 78→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, resumes(count)")
 79→        .eq("user_id", user.id)
 80→        .order("created_at", { ascending: false })
 81→        .limit(50);
 82→      if (jobs) {
 83→        setPastJobs(jobs.map((j: any) => ({
 84→          id: j.id,
 85→          title: j.title,
 86→          job_description: j.job_description,
 87→          status: j.status,
 88→          created_at: j.created_at,
 89→          resume_count: j.resumes?.[0]?.count ?? 0,
 90→          jd_analysis_json: j.jd_analysis_json,
 91→          dynamic_weights_json: j.dynamic_weights_json,
 92→        })));
 93→      }
 94→    } catch (err) {
 95→      console.error("Failed to load past jobs:", err);
 96→    } finally {
 97→      setLoadingPastJobs(false);
 98→    }
 99→  }, [user]);
100→
101→  useEffect(() => {
102→    fetchPastJobs();
103→  }, [fetchPastJobs]);
104→
105→  const loadJobData = async (jobId: string) => {
106→    setSelectedJobId(jobId);
107→    try {
108→      const [resumesRes, resumeListRes] = await Promise.all([
109→        supabase
110→          .from("resumes")
111→          .select("id, filename, file_path, candidate_name, created_at")
112→          .eq("job_id", jobId)
113→          .order("created_at", { ascending: false }),
114→        supabase
115→          .from("resumes")
116→          .select("id, filename, file_path, candidate_name, parsed_json")
117→          .eq("job_id", jobId),
118→      ]);
119→
120→      const resumes = resumesRes.data ?? [];
121→      setExistingResumes(resumes);
122→
123→      const resumeData = (resumeListRes.data ?? []) as Array<{
124→        id: string;
125→        filename: string;
126→        file_path: string | null;
127→        candidate_name: string | null;
128→        parsed_json?: any;
129→      }>;
130→      if (resumeData.length === 0) {
131→        setResults([]);
132→        return;
133→      }
134→
135→      const resumeIds = resumeData.map((r) => r.id);
136→      const { data: resultData } = await supabase
137→        .from("results")
138→        .select("id, resume_id, skill_score, experience_score, education_score, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
139→        .in("resume_id", resumeIds);
140→
141→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
142→      const merged: Result[] = (resultData ?? []).map((r: any) => {
143→        const resume = resumeMap.get(r.resume_id);
144→        const parsed = resume?.parsed_json as any;
145→        return {
146→          ...r,
147→          skill_score: r.skill_score ?? 0,
148→          experience_score: r.experience_score ?? 0,
149→          education_score: r.education_score ?? 0,
150→          overall_score: r.overall_score ?? 0,
151→          missing_skills: r.missing_skills ?? [],
152→          filename: resume?.filename ?? "Unknown",
153→          file_path: resume?.file_path ?? null,
154→          candidate_name: resume?.candidate_name ?? null,
155→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
156→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
157→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
158→        };
159→      });
160→      merged.sort((a, b) => b.overall_score - a.overall_score);
161→      setResults(merged);
162→    } catch (err) {
163→      console.error("Failed to load job data:", err);
164→      toast.error("Failed to load job data");
165→    }
166→  };
167→
168→  const handleNewJob = () => {
169→    setSelectedJobId(null);
170→    setResults([]);
171→    setExistingResumes([]);
172→  };
173→
174→  const handleJobCreated = (job: PastJob) => {
175→    setPastJobs((prev) => [job, ...prev]);
176→    setSelectedJobId(job.id);
177→    loadJobData(job.id);
178→  };
179→
180→  const handleRenameJob = (jobId: string, newTitle: string) => {
181→    setPastJobs((prev) =>
182→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
183→    );
184→  };
185→
186→  const handleDeleteJob = async (jobId: string) => {
187→    try {
188→      await supabase.from("resumes").delete().eq("job_id", jobId);
189→      await supabase.from("jobs").delete().eq("id", jobId);
190→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
191→      if (selectedJobId === jobId) handleNewJob();
192→      toast.success("Job deleted");
193→    } catch {
194→      toast.error("Failed to delete job");
195→    }
196→  };
197→
198→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
199→    setPastJobs((prev) =>
200→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
201→    );
202→  };
203→
204→  const requireAuth = useCallback(() => {
205→    if (!user) { setAuthOpen(true); return true; }
206→    return false;
207→  }, [user]);
208→
209→  return (
210→    <SidebarProvider className="h-svh overflow-hidden">
211→      <JobSidebar
212→        pastJobs={pastJobs}
213→        selectedJobId={selectedJobId}
214→        loadingPastJobs={loadingPastJobs}
215→        onSelectJob={loadJobData}
216→        onNewJob={handleNewJob}
217→        onRenameJob={handleRenameJob}
218→        onDeleteJob={handleDeleteJob}
219→        onAuthRequired={() => setAuthOpen(true)}
220→        isAuthenticated={!!user}
221→      />
222→
223→      <SidebarInset className="h-svh overflow-y-auto">
224→        <AppHeader />
225→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
226→          <SidebarTrigger />
227→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
228→        </div>
229→        <JobDetailView
230→          selectedJobId={selectedJobId}
231→          selectedJob={selectedJob}
232→          results={results}
233→          setResults={setResults}
234→          existingResumes={existingResumes}
235→          setExistingResumes={setExistingResumes}
236→          onJobCreated={handleJobCreated}
237→          onAuthRequired={() => setAuthOpen(true)}
238→          isAuthenticated={!!user}
239→          onJobUpdated={handleJobUpdated}
240→        />
241→      </SidebarInset>
242→
243→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
244→    </SidebarProvider>
245→  );
246→};
247→
248→export default Index;
