 63→export function useSeoSettings() {
 64→  const qc = useQueryClient();
 65→
 66→  const { data: settings, isLoading } = useQuery({
 67→    queryKey: ["seo_settings"],
 68→    queryFn: async () => {
 69→      const { data, error } = await (supabase as any)
 70→        .from("seo_settings")
 71→        .select("*")
 72→        .limit(1)
 73→        .single();
 74→      if (error) throw error;
 75→      return data as SeoSettings;
 76→    },
 77→    staleTime: 60_000,
 78→  });
 79→
 80→  useEffect(() => {
 81→    const channel = supabase
 82→      .channel("seo_settings_realtime")
 83→      .on(
 84→        "postgres_changes",
 85→        { event: "*", schema: "public", table: "seo_settings" },
 86→        () => {
 87→          qc.invalidateQueries({ queryKey: ["seo_settings"] });
 88→        }
 89→      )
 90→      .subscribe();
 91→
 92→    return () => {
 93→      supabase.removeChannel(channel);
 94→    };
 95→  }, [qc]);
 96→
 97→  return { settings, isLoading };
 98→}
